        self.update_queue = []
        self.next_queue = []
        if value is not None:
            for i in range(32):
                self.values[i] = (value >> i) & 1

    def parse(self, gates_file):
        for line in open(gates_file):
            line = line.strip()
            m = re.match(r'out(\d+) = (.*)$', line)
            if not m:
                continue
            out_idx = int(m.group(1))
            op = m.group(2).strip()
            self.num_signals = max(self.num_signals, out_idx+1)
            if op == '0':
                self.gates[out_idx] = ('const', 0)
            elif op == '1':
                self.gates[out_idx] = ('const', 1)
            elif re.fullmatch(r'out\d+', op):
                src = int(op[3:])
                self.gates[out_idx] = ('copy', src)
                self.dependents[src].append(out_idx)
            elif op.startswith('~out') and ' ' not in op:
                src = int(op[4:])
                self.gates[out_idx] = ('not', src)
                self.dependents[src].append(out_idx)
            else:
                mm = re.match(r'out(\d+) ([&|^]) out(\d+)', op)
                if mm:
                    src1, opc, src2 = int(mm.group(1)), mm.group(2), int(mm.group(3))
                    self.gates[out_idx] = (opc, src1, src2)
                    self.dependents[src1].append(out_idx)
                    self.dependents[src2].append(out_idx)

    def heap_push(self, q, signal):
        heapq.heappush(q, signal)

    def heap_pop(self, q):
        return heapq.heappop(q) if q else -1

    def simulate_step(self):
        if self.step_number > 0:
            self.update_queue = self.next_queue
            self.next_queue = []
        self.next_queue = []
        self.in_queue = [0]*self.num_signals
        self.next_in_queue = [0]*self.num_signals
        self.did = [0]*self.num_signals
        if self.step_number == 0:
            for i in range(self.num_signals):
                self.heap_push(self.update_queue, i)
                self.in_queue[i] = 1
        while self.update_queue:
            sig = self.heap_pop(self.update_queue)
            if sig < 0 or sig >= MAX_SIGNALS:
                continue
            if self.did[sig]:
                continue
            self.did[sig] = 1
            old_value = self.values[sig]
            g = self.gates[sig]
            t = g[0]
            if t == 'const':
                newval = g[1]
            elif t == 'copy':
                newval = self.values[g[1]]
            elif t == 'not':
                newval = 0 if self.values[g[1]] else 1
            elif t == '&':
                newval = self.values[g[1]] & self.values[g[2]]
            elif t == '|':
                newval = self.values[g[1]] | self.values[g[2]]
            elif t == '^':
                newval = self.values[g[1]] ^ self.values[g[2]]
            else:
                newval = 0
            if newval != old_value:
