# Prototype of the sequential algorithm:
# State: c (count), sq=c*c, a=F_c, b=F_{c+1}
# f: if (c+1)^2 <= N and c != 0xFFFF: advance (c->c+1, sq->(c+1)^2, a->b, b->a+b)
#    else hold.
# Pipelined register: after step k (0-indexed), state = f^{3*(k-1)}(0) for k>=1.
MOD = 1 << 32

def fib_expected(m):
    a, b = 0, 1
    for _ in range(m):
        a, b = b, (a + b) % MOD
    return a

def isqrt(n):
    k = 0
    while (k+1)*(k+1) <= n:
        k += 1
    return k

def step(state, N):
    c, sq, a, b = state
    c1 = c + 1
    sq_next = sq + 2*c + 1  # (c+1)^2 ; for c=0xffff this overflows 2^32, handled by cond
    # condition to advance
    if c != 0xFFFF and sq_next <= N:
        return (c1, sq_next % MOD, b, (a + b) % MOD)
    else:
        return state

def simulate_pipeline(N, total_steps=32000, K=3):
    state = (0, 0, 0, 1)   # c=0, sq=0, a=F0=0, b=F1=1
    # RD_prev (pipeline delay): treat initial RD as f^0? Let's model the actual
